import React, { useMemo } from 'react';
import { guiPropsToStyle } from '../../common/utils/guiPropsToStyle.js';
import { slotKeys, commonSlotWrapperStyles, getSlotStyle, Slots } from '../constants/slotOverlayLayoutConfig.js';

// `containerOverrides` are merged inline and win over the classes (inline beats utility specificity).
const overlayContainerClassName = 'relative block size-full clip';
const baseOverlayContainerStyle = {
    boxSizing: 'border-box',
    background: 'transparent'
};
const slotWrapperClassName = 'absolute pointer-events-none';
const SlotOverlay = ({ topLeftSlot, topMiddleSlot, topRightSlot, centerLeftSlot, centerMiddleSlot, centerRightSlot, bottomLeftSlot, bottomMiddleSlot, bottomRightSlot, padding = 0, containerOverrides, children }) => {
    const containerStyle = useMemo(() => {
        return {
            ...baseOverlayContainerStyle,
            ...(containerOverrides ? guiPropsToStyle(containerOverrides) : {})
        };
    }, [containerOverrides]);
    const slotPropsMap = useMemo(() => {
        return {
            topLeftSlot,
            topMiddleSlot,
            topRightSlot,
            centerLeftSlot,
            centerMiddleSlot,
            centerRightSlot,
            bottomLeftSlot,
            bottomMiddleSlot,
            bottomRightSlot
        };
    }, [
        topLeftSlot,
        topMiddleSlot,
        topRightSlot,
        centerLeftSlot,
        centerMiddleSlot,
        centerRightSlot,
        bottomLeftSlot,
        bottomMiddleSlot,
        bottomRightSlot
    ]);
    const slotElements = useMemo(() => {
        return slotKeys
            .map(propName => {
            const slotContent = slotPropsMap[propName];
            if (slotContent) {
                // commonSlotWrapperStyles + per-slot positioning + padding, all inline.
                const slotStyle = {
                    ...commonSlotWrapperStyles,
                    ...getSlotStyle(Slots[propName]),
                    padding: `${padding}px`
                };
                return (React.createElement("div", { key: propName, className: slotWrapperClassName, style: slotStyle, "data-testid": `slot-wrapper-${propName}` }, slotContent));
            }
            return null;
        })
            .filter(e => e !== null);
    }, [slotPropsMap, padding]);
    return (React.createElement("div", { className: overlayContainerClassName, style: containerStyle, "data-testid": 'slot-overlay-container' },
        children,
        slotElements));
};

export { SlotOverlay as default };
